const items = $input.all();
if (!items || items.length === 0) return [];

function cleanPart(value) {
  return String(value || '').trim().replace(/\s+/g, ' ');
}

function normalizeOrg(value) {
  const org = cleanPart(value);
  if (!org) return 'Activecenter';
  return org.toUpperCase() === 'ACTIVECENTER' ? 'Activecenter' : org;
}

function formatPhone(prefix, number) {
  const cleanPrefix = String(prefix || '').replace(/[^\d+]/g, '');
  const cleanNumber = String(number || '').replace(/[^\d]/g, '');
  if (!cleanPrefix && !cleanNumber) return '';
  if (!cleanPrefix) return cleanNumber;
  if (!cleanNumber) return cleanPrefix.startsWith('+') ? cleanPrefix : '+' + cleanPrefix;
  const intlPrefix = cleanPrefix.startsWith('+') ? cleanPrefix : '+' + cleanPrefix;
  const firstChunk = cleanNumber.slice(0, 3);
  const rest = cleanNumber.slice(3);
  return rest ? intlPrefix + ' ' + firstChunk + ' ' + rest : intlPrefix + ' ' + firstChunk;
}

return items.map(item => {
  const row = item.json;
  const phone = formatPhone(row.coach_phone_prefix, row.coach_phone);
  const coachFirstName = cleanPart(row.coach_first_name);
  const coachLastName = cleanPart(row.coach_last_name || row.coach_full_name);
  const coachName = [coachFirstName, coachLastName].filter(Boolean).join(' ').trim();
  const org = normalizeOrg(row.coach_organisation_name);

  return {
    json: {
      contact_id: String(row.contact_id || ''),
      contact_email: cleanPart(row.contact_email),
      contact_first_name: cleanPart(row.contact_first_name),
      contact_last_name: cleanPart(row.contact_last_name),
      coach_first_name: coachFirstName,
      coach_last_name: coachLastName,
      coach_full_name: coachName,
      coach_email: cleanPart(row.coach_email),
      coach_phone: phone,
      coach_slug: cleanPart(row.coach_slug),
      coach_organisation_name: org,
      coach_org_display: org,
      coach_display_name: [coachName, org].filter(Boolean).join(' - ')
    }
  };
});

const mauticResponse = $json;
const contacts = Object.values(mauticResponse.contacts || {});

if (!contacts.length) {
  return [{ json: { skip: true, reason: 'contact not found in Mautic', contact_id: $('Code - Normalize Contact Data').item.json.contact_id } }];
}

const mauticContact = contacts[0];
const mysqlData = $('Code - Normalize Contact Data').item.json;
const fields = mauticContact.fields?.all || {};

function fieldValue(alias) {
  const raw = fields[alias];
  if (raw && typeof raw === 'object') return String(raw.value ?? '').trim();
  return String(raw ?? '').trim();
}

function same(alias, value) {
  return fieldValue(alias) === String(value || '').trim();
}

const updatePayload = {
  ac_berater_vorname: mysqlData.coach_first_name,
  ac_berater_name: mysqlData.coach_last_name,
  ac_berater_email: mysqlData.coach_email,
  ac_berater_whatsapp: mysqlData.coach_phone,
  ac_berater_slug: mysqlData.coach_slug,
  ac_berater_organisation: mysqlData.coach_organisation_name,
  ac_berater_display_name: mysqlData.coach_display_name,
  ac_berater_org_display: mysqlData.coach_org_display
};

const needsUpdate = Object.entries(updatePayload).some(([alias, value]) => !same(alias, value));

if (!needsUpdate) {
  return [{ json: { skip: true, reason: 'no changes', mauticContactId: mauticContact.id } }];
}

return [{
  json: {
    skip: false,
    mauticContactId: mauticContact.id,
    updatePayload
  }
}];
